INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES 
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Um paciente submetido a cirurgia de bypass gástrico em Y-de-Roux desenvolve dor abdominal em cólica e vômitos no 15º DPO. A tomografia de abdome sugere o ''sinal do redemoinho'' (whirl sign). Qual a complicação específica?", "options": {"a": "Apendicite aguda residual.", "b": "Hérnia interna através do espaço de Petersen.", "c": "Colecistite aguda.", "d": "Sindrome de Dumping precoce.", "e": "Úlcera de boca anastomótica."}, "answer": "b", "rationale": "A hérnia interna é uma complicação potencialmente fatal da cirurgia bariátrica, onde alças de intestino de herniam através de espaços criados pela reconstrução em Y-de-Roux.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Diagnóstico radiológico e clínico clássico.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "media", "tags": ["Cirurgia Bariátrica", "Pós-operatório", "Hérnia Interna", "Ogilvie"]}', 191, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "No pós-operatório de uma tireoidectomia total, o paciente apresenta rouquidão persistente. No entanto, ele consegue falar, mas queixa-se de cansaço vocal e incapacidade de atingir tons agudos (perda da voz de canto). Qual o nervo provavelmente lesionado?", "options": {"a": "Nervo Laríngeo Recorrente unilateral.", "b": "Nervo Laríngeo Superior (ramo externo).", "c": "Nervo Glossofaríngeo.", "d": "Nervo Laríngeo Recorrente bilateral.", "e": "Nervo Vago tronco."}, "answer": "b", "rationale": "O ramo externo do nervo laríngeo superior inerva o músculo cricotireóideo, responsável por tensionar as pregas vocais para tons agudos. Sua lesão causa fadiga vocal.", "option_rationales": {"a": "Incorreta. Causaria rouquidão franca e voz soprosa.", "b": "Correta. Nervo do cantor/tons agudos.", "c": "Incorreta.", "d": "Incorreta. Causaria estridor e insuficiência respiratória.", "e": "Incorreta."}, "difficulty": "media", "tags": ["Cirurgia de Cabeça e Pescoço", "Pós-operatório", "Nervo Laríngeo", "Tireoidectomia"]}', 192, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "A complicação de estoma conhecida como ''isquemia ou necrose de estoma'' nas primeiras 24 horas após a confecção de uma colostomia é causada principalmente por:", "options": {"a": "Falta de higiene do paciente.", "b": "Tensão excessiva no mesentério ou ligadura de vasos terminais que suprem a alça exteriorizada.", "c": "Uso de bolsa de colostomia apertada.", "d": "Alergia ao material plástico.", "e": "Diarreia profusa."}, "answer": "b", "rationale": "A viabilidade do estoma depende da preservação da irrigação sanguínea. A necrose exige reoperação se atingir níveis abaixo da fáscia.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Causa técnica vascular primária.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Cirurgia Geral", "Pós-operatório", "Colostomia", "Necrose"]}', 193, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Um paciente submetido a prostatectomia radical laparoscópica apresenta no 2º DPO dor abdominal e distensão. O dreno pélvico apresenta débito alto de líquido citrino. A creatinina do líquido do dreno é de 15 mg/dL, enquanto a creatinina sérica é de 1,1 mg/dL. Qual o diagnóstico?", "options": {"a": "Ascite quilosa.", "b": "Fístula urinária (Urinoma).", "c": "Linfonodo roto.", "d": "Hemorragia ativa.", "e": "Peritonite bacteriana."}, "answer": "b", "rationale": "A creatinina no líquido do dreno muito superior à creatinina sérica confirma a presença de urina na cavidade (urinoma).", "option_rationales": {"a": "Incorreta.", "b": "Correta. Teste bioquímico confirmatório para fístula urinária.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Urologia", "Pós-operatório", "Fístula Urinária", "Diagnóstico"]}', 194, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Qual a principal causa de ''hipotensão e bradicardia'' súbita logo após a realização de uma Raquianestesia, antes do início da cirurgia?", "options": {"a": "Hemorragia oculta.", "b": "Bloqueio simpático (simpatectomia química) levando a vasodilatação periférica e redução do retorno venoso.", "c": "Reação anafilática ao látex.", "d": "Infarto agudo.", "e": "Embolia por líquido amniótico."}, "answer": "b", "rationale": "O anestésico local no espaço subaracnóideo bloqueia as fibras simpáticas pré-ganglionares, resultando em queda da resistência vascular sistêmica.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Efeito fisiológico esperado e complicação hemodinâmica comum do neuroeixo.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Anestesiologia", "Pós-operatório", "Raquianestesia", "Simpatectomia"]}', 195, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Um paciente de 60 anos submetido a correção de hérnia inguinal sob raquianestesia não consegue urinar 6 horas após o procedimento, apesar de estar com a bexiga visivelmente distendida e dolorosa. Qual o manejo?", "options": {"a": "Administrar diuréticos.", "b": "Realizar cateterismo vesical de alívio.", "c": "Pedir para o paciente tentar urinar no banho morno e aguardar mais 4 horas.", "d": "Iniciar antibiótico para ITU.", "e": "Encaminhar para cirurgia urológica urgente."}, "answer": "b", "rationale": "A retenção urinária aguda no pós-operatório (RUPO) é comum após raquianestesia. O alívio mecânico com sonda é necessário se as manobras iniciais falharem.", "option_rationales": {"a": "Incorreta. Piora a distensão vesical.", "b": "Correta. Conduta de alívio padrão.", "c": "Incorreta. Atrasar o alívio pode causar lesão do detrusor por estiramento excessivo.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Urologia", "Pós-operatório", "Retenção Urinária", "Manejo"]}', 196, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "No pós-operatório de uma gastrectomia subtotal por úlcera gástrica, o paciente desenvolve quadro de vômitos biliosos que ocorrem cerca de 30-60 minutos após a ingestão de alimentos, com alívio imediato da dor após o vômito. Qual a causa provável?", "options": {"a": "Sindrome de Dumping.", "b": "Sindrome da Alça Aferente.", "c": "Gangrena gástrica.", "d": "Gastrite erosiva aguda.", "e": "Sindrome do Intestino Curto."}, "answer": "b", "rationale": "Ocorre em reconstruções tipo Billroth II. A bile se acumula na alça aferente obstruída e, quando a pressão vence a resistência, ela extravasa para o estômago, causando o vômito bilioso sem alimentos.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Complicação específica da anatomia cirúrgica Billroth II.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "moderada", "tags": ["Cirurgia Geral", "Pós-operatório", "Alça Aferente", "Gastrectomia"]}', 197, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Em pacientes idosos submetidos a cirurgias ortopédicas de grande porte, qual a estratégia farmacológica de escolha para a profilaxia química de Tromboembolismo Venoso (TEV), caso não haja contraindicações?", "options": {"a": "AAS (Ácido Acetilsalicílico) isolado.", "b": "Heparina de Baixo Peso Molecular (como Enoxaparina) ou Fondaparinux.", "c": "Varfarina visando RNI de 4,0.", "d": "Clopidogrel.", "e": "Vitamina K."}, "answer": "b", "rationale": "A HBPM e o Fondaparinux são superiores ao AAS na prevenção de TVP/TEP em pacientes cirúrgicos de alto risco ortopédico.", "option_rationales": {"a": "Incorreta. Menor eficácia que heparinas.", "b": "Correta. Padrão-ouro em profilaxia química perioperatória.", "c": "Incorreta. Difícil manejo e exige tempo para atingir o alvo.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Ortopedia", "Pós-operatório", "TEV", "Profilaxia"]}', 198, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "A complicação conhecida como ''Evisceração'' é uma emergência cirúrgica que consiste em:", "options": {"a": "Saída parcial de gordura subcutânea pela pele.", "b": "Saída de víscera (geralmente intestino) através da deiscência completa de todos os planos da parede abdominal.", "c": "Presença de hérnia incisional definitiva após 1 ano.", "d": "Infecção profunda com pus no músculo.", "e": "Encurtamento do intestino.", "answer": "b", "rationale": "Diferente da deiscência apenas da fáscia (subclínica inicial), a evisceração ocorre quando a pele também abre e o conteúdo abdominal se exterioriza.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Definição correta do termo.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "answer": "b", "difficulty": "facil", "tags": ["Cirurgia Geral", "Pós-operatório", "Evisceração", "Definição"]}', 199, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Um paciente submetido a colecistectomia evolui com febre no 7º DPO. O cirurgião suspeita de abscesso intra-abdominal. Qual o exame de imagem com MAIOR ACURÁCIA (especificidade) para localizar coleções líquidas intra-abdominais no pós-operatório?", "options": {"a": "Raio-x de abdome agudo.", "b": "Ultrassonografia abdominal.", "c": "Tomografia Computadorizada de Abdome com Contraste (Venoso e Enteral).", "d": "Cintilografia com gálio.", "e": "Colonoscopia."}, "answer": "c", "rationale": "A TC com contraste permite identificar coleções, diferenciar pus de ar e planejar a drenagem percutânea.", "option_rationales": {"a": "Incorreta.", "b": "Incorreta. Operador-dependente e difícil em pós-operatório com gazes/drenos.", "c": "Correta. Exame de escolha para complicações infecciosas cavitárias.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Cirurgia Geral", "Pós-operatório", "Abscesso", "TC"]}', 200, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "A deiscência da anastomose esôfago-jejunal após gastrectomia total manifesta-se frequentemente por qual sinal precoce no dreno cervical ou mediastinal?", "options": {"a": "Saída de saliva e ar (se for cervical) ou febre persistente e aumento da amilase no líquido drenado.", "b": "Bile pura.", "c": "Fezes formadas.", "d": "Sangue arterial vivo.", "e": "Líquido cefalorraquidiano."}, "answer": "a", "rationale": "Fístulas de esôfago liberam saliva e ar. A amilase salivar no líquido de drenagem é um marcador bioquímico útil para diagnóstico.", "option_rationales": {"a": "Correta. Semiologia de deiscência esofágica.", "b": "Incorreta. Bile sugeria fístula mais distal.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "media", "tags": ["Cirurgia do Aparelho Digestivo", "Pós-operatório", "Fístula Esofágica", "Marcardores"]}', 201, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Em pacientes submetidos a amputação de membros inferiores, a sensação dolorosa referida no membro que já não existe é chamada de:", "options": {"a": "Alodinia cutânea.", "b": "Dor Fantasma.", "c": "Sindrome de Brown-Séquard.", "d": "Neuropatia diabética.", "e": "Agonasia motora."}, "answer": "b", "rationale": "A dor fantasma é uma dor neuropática central por reorganização sensorial no córtex cerebral após perda do input periférico.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Fenômeno de dor crônica pós-operatória específico.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Ortopedia", "Pós-operatório", "Dor Fantasma", "Amputação"]}', 202, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Qual a principal complicação de uma paralisia bilateral dos nervos laríngeos recorrentes após uma tireoidectomia total?", "options": {"a": "Rouquidão leve.", "b": "Obstrução respiratória alta (por fechamento das pregas vocais na linha média).", "c": "Perda de paladar.", "d": "Disfagia para líquidos apenas.", "e": "Diminuição da frequência cardíaca."}, "answer": "b", "rationale": "O laríngeo recorrente inerva quase todos os músculos intrínsecos da laringe. Na paralisia bilateral, as pregas vocais podem ficar em posição paramediana, causando asfixia e exigindo traqueostomia de urgência.", "option_rationales": {"a": "Incorreta. Rouquidão é na unilateral.", "b": "Correta. Emergência respiratória cirúrgica.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "media", "tags": ["Cirurgia de Cabeça e Pescoço", "Pós-operatório", "Nervo Laríngeo", "Emergência"]}', 203, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Um paciente no 5º DPO de cirurgia de colo desenvolve distensão abdominal e radiografia mostra alças delgadas dilatadas com níveis hidroaéreos. O paciente não elimina gases. O diagnóstico é Obstrução Intestinal por Aderências (Brida). Qual a conduta inicial recomendada no paciente estável e sem sinais de estrangulamento?", "options": {"a": "Operar imediatamente.", "b": "Tratamento conservador com jejum, hidratação venosa e passagem de sonda nasogástrica (SNG) para descompressão.", "c": "Fazer clister de bário.", "d": "Apenas observar sem sonda.", "e": "Iniciar quimioterapia."}, "answer": "b", "rationale": "A maioria das bridas pós-operatórias precoces se resolve com manejo conservador. A cirurgia é indicada se houver sinais de peritonite ou falha do tratamento conservador após 48-72h.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Conduta padrão inicial para bridas estáveis.", "c": "Incorreta.", "d": "Incorreta. A SNG é fundamental para conforto e descompressão.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Cirurgia Geral", "Pós-operatório", "Obstrução Intestinal", "Manejo"]}', 204, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Qual a principal alteração do equilíbrio ácido-básico em um paciente com vômitos profusos secundários a uma obstrução gástrica pós-operatória?", "options": {"a": "Acidose metabólica hiperclorêmica.", "b": "Alcalose metabólica hipoclorêmica e hipocalêmica.", "c": "Acidose respiratória compensada.", "d": "Alcalose respiratória aguda.", "e": "Gap aniônico elevado com cetose."}, "answer": "b", "rationale": "A perda de suco gástrico rico em HCl (hidrogênio e cloro) leva à alcalose. A perda de volemia estimula a renina-angiotensina, que espolia potássio pelo rim.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Distúrbio clássico da perda de secreção ácida gástrica.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "media", "tags": ["Clínica Médica", "Pós-operatório", "Eletrólitos", "Alcalose"]}', 205, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "No 2º DPO de uma revascularização cardíaca, o paciente apresenta agitação psicomotora e tenta arrancar os acessos venosos. O quadro inicia-se à noite e melhora pela manhã. Qual o manejo inicial recomendado antes de qualquer sedação?", "options": {"a": "Internação em quarto escuro e isolamento.", "b": "Promoção de ciclo sono-vigília, luz natural durante o dia, presença de acompanhante familiar e correção de distúrbios de base.", "c": "Uso de contenção mecânica apenas.", "d": "Administração de benzodiazepínicos em bólus repetidos.", "e": "Transferência imediata para psiquiatria."}, "answer": "b", "rationale": "O tratamento do delirium começa com medidas não farmacológicas para reorientar o paciente. Benzodiazepínicos devem ser evitados, pois podem piorar o delirium no idoso (efeito paradoxal).", "option_rationales": {"a": "Incorreta. Piora a desorientação.", "b": "Correta. Manejo do Delirium foco em prevenção e reorientação.", "c": "Incorreta. Aumenta a agitação e risco de lesão.", "d": "Incorreta. Fármacos de escolha seriam antipsicóticos em baixas doses se necessário.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Geriátria", "Pós-operatório", "Delirium", "Manejo"]}', 206, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "A complicação conhecida como ''quilotórax'' após esofagectomia pode ser tratada inicialmente de forma conservadora. Qual a base dietética deste tratamento para reduzir o débito de quilo?", "options": {"a": "Dieta rica em gorduras animais.", "b": "Dieta zero ou dieta com Triglicerídeos de Cadeia Média (TCM), que são absorvidos diretamente pela veia porta sem passar pelos linfáticos.", "c": "Dieta rica em fibras.", "d": "Uso de apenas líquidos clarificados.", "e": "Mistura de óleos vegetais."}, "answer": "b", "rationale": "O quilo é formado a partir de gorduras de cadeia longa. O uso de TCM reduz a produção de quilo e permite que a fístula linfática feche espontaneamente em muitos casos.", "option_rationales": {"a": "Incorreta. Pioraria muito o débito.", "b": "Correta. Manejo nutricional específico para fístulas linfáticas.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "media", "tags": ["Cirurgia Torácica", "Pós-operatório", "Quilotórax", "Nutrição"]}', 207, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Um paciente submetido a cirurgia oncológica extensa recebe Nutrição Parenteral Total (NPT) por veia central. No 4º dia, desenvolve febre de 39°C e fungemia (Cândida no sangue). Qual a conduta prioritária além da antifungicoterapia?", "options": {"a": "Manter o acesso central a todo custo.", "b": "Retirada imediata do cateter venoso central suspeito.", "c": "Dobrar a dose da NPT.", "d": "Realizar laparotomia exploradora.", "e": "Trocar apenas o filtro da NPT."}, "answer": "b", "rationale": "A IPCS por fungos é indicação absoluta de retirada do cateter central, pois os fungos colonizam o cateter formando biofilmes resistentes.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Conduta padrão em IPCS fúngica.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Terapia Intensiva", "Pós-operatório", "NPT", "IPCS"]}', 208, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "No pós-operatório imediato de uma neurocirurgia complexa, o paciente apresenta hiponatremia severa (Sódio de 125 mEq/L) mas com volume intravascular NORMAL (euvolemia) e urina concentrada. Qual o diagnóstico mais provável?", "options": {"a": "Diabetes Insipidus.", "b": "SIADH (Síndrome da Secreção Inapropriada de ADH).", "c": "Cerebral Salt Wasting (Perda cerebral de sal).", "d": "Intoxicação hídrica por soro glicosado.", "e": "Choque Séptico."}, "answer": "b", "rationale": "A SIADH após trauma/cirurgia craniana leva à retenção excessiva de água livre, diluindo o sódio plasmático em um paciente que não apresenta sinais de desidratação ou edema.", "option_rationales": {"a": "Incorreta. Causaria hipernatremia.", "b": "Correta. Quadro clínico de hiponatremia euvolêmica.", "c": "Incorreta. Cerebral Salt Wasting cursa com hipovolemia (desidratação).", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "moderada", "tags": ["Neurocirurgia", "Pós-operatório", "SIADH", "Hiponatremia"]}', 209, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "A principal causa de ''anemia megablástica'' (macrocítica) em pacientes submetidos a gastrectomia total, que se manifesta após 3 a 5 anos da cirurgia se não houver reposição, é:", "options": {"a": "Falta de ácido clorídrico.", "b": "Falha na produção de fator intrínseco e consequente má absorção de Vitamina B12.", "c": "Perda de sangue crônica.", "d": "Intoxicação por metais pesados.", "e": "Hipotiroidismo pós-cirúrgico."}, "answer": "b", "rationale": "As células parietais do estômago produzem fator intrínseco, necessário para a absorção da B12 no íleo terminal. Sem o estômago, o estoque corporal de B12 (que dura anos) se esgota.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Fisiopatologia da anemia perniciosa adquirida pós-gastrectomia.", "c": "Incorreta. Ferro daria anemia microcítica.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Cirurgia do Aparelho Digestivo", "Pós-operatório", "Vitamina B12", "Gastrectomia"]}', 210, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Qual a principal complicação iatrogênica do uso de cateter de Swan-Ganz (cateter de artéria pulmonar) durante a monitorização hemodinâmica em cirurgia cardíaca?", "options": {"a": "Ruptura de artéria pulmonar.", "b": "Infarto esplênico.", "c": "Perfuração gástrica.", "d": "AVC isquêmico.", "e": "Lesão do nervo radial."}, "answer": "a", "rationale": "A migração inadvertida da ponta do cateter para um ramo distal e a insuflação do balonete podem causar a ruptura do vaso, levando a hemorragia pulmonar fulminante.", "option_rationales": {"a": "Correta. Complicação rara mas catastrófica da monitorização invasiva.", "b": "Incorreta.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "media", "tags": ["Terapia Intensiva", "Pós-operatório", "Monitorização Invasiva", "Swan-Ganz"]}', 211, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Um paciente submetido a cirurgia oncológica de pelve desenvolve quadro de linfedema severo em membro inferior direito no 15º DPO. Qual a explicação anatômica?", "options": {"a": "Trombose venosa profunda obstrutiva.", "b": "Lesão ou ressecção extensa de cadeias linfáticas ilíacas e inguinais (Linfadenectomia) impedindo o retorno linfático.", "c": "Insuficiência cardíaca direita.", "d": "Falta de proteínas na dieta.", "e": "Celulite aguda."}, "answer": "b", "rationale": "O linfedema secundário é uma consequência comum da disrupção mecânica dos canais linfáticos durante cirurgias radicais oncológicas com esvaziamento ganglionar.", "option_rationales": {"a": "Incorreta. TVP dá edema venoso, não linfedema tipicamente (embora coexistam no diagnóstico diferencial).", "b": "Correta. Mecanismo direto pós-linfadenectomia.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Oncologia", "Pós-operatório", "Linfedema", "Complicações"]}', 212, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "No pós-operatório de uma cesariana, a paciente apresenta quadro de dor abdominal suprapúbica, febre, útero amolecido e doloroso à palpação, e loquios fétidos. Qual o diagnóstico?", "options": {"a": "Apendicite aguda.", "b": "Endometrite pós-parto.", "c": "Cistite.", "d": "Colecistite.", "e": "Deiscência da cicatriz abdominal apenas."}, "answer": "b", "rationale": "A endometrite é a complicação infecciosa mais comum após cesariana, caracterizada pela tríade de febre, dor uterina e loquios fétidos.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Infecção de sítio cirúrgico ginecológico.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Ginecologia e Obstetrícia", "Pós-operatório", "Endometrite"]}', 213, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Qual complicação de cicatrização caracteriza-se por uma proliferação excessiva de tecido fibroso (colágeno) que ultrapassa os limites da cicatriz original e não involui espontaneamente?", "options": {"a": "Cicatriz hipertrófica.", "b": "Queloide.", "c": "Seroma calcificado.", "d": "Fibromatose agressiva.", "e": "Granuloma de fio."}, "answer": "b", "rationale": "O queloide é um tumor benigno de colágeno que se estende além da margem da ferida, diferente da cicatriz hipertrófica que fica restrita à linha da incisão.", "option_rationales": {"a": "Incorreta. Fica restrita à linha da cicatriz.", "b": "Correta. Definição correta do queloide.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Cirurgia Plástica", "Pós-operatório", "Cicatrização", "Queloide"]}', 214, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "A ocorrência de ''pneumoperitônio'' visto no Raio-x de abdome em pé ou em decúbito lateral (Cúpula diafragmática) no 1º e 2º dia após uma laparotomia deve ser interpretada como:", "options": {"a": "Sinal de perfuração de víscera oca imediata.", "b": "Achado esperado por ar residual que entrou na cavidade durante a abertura cirúrgica e que demora alguns dias para ser reabsorvido.", "c": "Indicação de reoperação urgente.", "d": "Sinal de insuficiência hepática.", "e": "Obstrução intestinal."}, "answer": "b", "rationale": "É normal haver ar residual por até 5-7 dias após cirurgia aberta (mais curto em laparoscopias). O diagnóstico de perfuração exige correlação com sinais de peritonite e febre.", "option_rationales": {"a": "Incorreta. Pode ser ar residual.", "b": "Correta. Evolução radiológica normal do pós-op de laparotomia.", "c": "Incorreta. Sem clínica de peritonite, não se opera apenas o raio-x.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Cirurgia Geral", "Pós-operatório", "Pneumoperitônio", "Radiologia"]}', 215, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Um paciente submetido a cirurgia no 10º andar do hospital desenvolve no 3º DPO hipotensão, taquicardia e distensao de jugulares. O cirurgião diagnostica choque obstrutivo. Qual das opções abaixo pode causar este padrão hemodinâmico no pós-operatório?", "options": {"a": "Choque Séptico por pneumonia.", "b": "Choque Hipovolêmico por hemorragia.", "c": "Tromboembolismo Pulmonar maciço.", "d": "IAM com choque cardiogênico.", "e": "Sindrome do Intestino Curto."}, "answer": "c", "rationale": "O choque obstrutivo (TEP maciço, tamponamento cardíaco ou pneumotórax hipertensivo) caracteriza-se por turgência jugular (aumento da PVC) associada a hipotensão e baixo débito cardíaco por impedimento mecânico.", "option_rationales": {"a": "Incorreta. Distensao jugular não é comum no choque distributivo puro.", "b": "Incorreta. Jugulares estariam colabadas.", "c": "Correta. Causa frequente de choque obstrutivo pós-operatório.", "d": "Incorreta. Embora tenha turgência, o principal mecanismo é falha de bomba, mas o TEP é um diferencial clássico em pacientes cirúrgicos.", "e": "Incorreta."}, "difficulty": "media", "tags": ["Cardiologia", "Pós-operatório", "Choque Obstrutivo", "TEP"]}', 216, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "A principal vantagem da anestesia peridural torácica associada à anestesia geral em cirurgias abdominais altas e torácicas no que diz respeito ao sistema respiratório?", "options": {"a": "Aumenta a força dos músculos intercostais.", "b": "Permite melhor controle da dor, favorecendo respirações profundas e tosse eficaz, reduzindo atelectasias.", "c": "Reduz o risco de embolia gordurosa.", "d": "Impede a ocorrência de náuseas.", "e": "Acelera o tempo de esvaziamento gástrico."}, "answer": "b", "rationale": "A analgesia regional superior permite que o paciente respire melhor sem a limitação álgica, o que é fundamental para evitar complicações pulmonares restritivas.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Principal benefício respiratório da analgesia epidural.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "media", "tags": ["Anestesiologia", "Pós-operatório", "Analgesia Epidural", "Pulmonar"]}', 217, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "No 3º DPO de uma esternotomia mediana por troca valvar, o dreno mediastinal apresenta saída de líquido límpido pálido com aparência de soro. Qual a explicação mais provável se este líquido for quilo?", "options": {"a": "Derrame pleural por IC.", "b": "Lesão do ducto torácico ou seus ramos durante a dissecção mediastinal.", "c": "Pericardite aguda.", "d": "Abscesso mediastinal precoce.", "e": "Fístula gástrica para o tórax."}, "answer": "b", "rationale": "O quilotórax/quilomediastino no pós-operatório cardíaco ocorre por trauma inadvertido do ducto torácico.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Complicação anatômica traumática.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "media", "tags": ["Cirurgia Cardíaca", "Pós-operatório", "Quilotórax", "Ducto Torácico"]}', 218, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Um paciente submetido a cirurgia oncológica de reto apresenta no 7º DPO saída de ar e fezes pela vagina (Fístula Retovaginal). Qual a causa técnica provável desta fístula em cirurgias com anastomose colorretal baixa?", "options": {"a": "Infecção urinária.", "b": "Lesão inadvertida da parede vaginal posterior durante a dissecção do espaço retovaginal ou inclusão da vagina no grampeamento da anastomose.", "c": "Diarreia infecciosa.", "d": "Uso de papel higiênico áspero.", "e": "Menopausa precoce."}, "answer": "b", "rationale": "A fístula retovaginal no pós-op imediato sugere trauma cirúrgico direto ou isquemia por grampeamento acidental de parte da vagina.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Mecanismo de lesão técnica iatrogênica.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "media", "tags": ["Proctologia", "Pós-operatório", "Fístula", "Complicações"]}', 219, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "No pós-operatório de uma cirurgia abdominal, o paciente desenvolve quadro de colite com diarreia profusa, dor abdominal e febre após o uso de antibióticos por 7 dias. O teste de toxina nas fezes é positivo para Clostridioides difficile. Qual o tratamento de primeira linha recomendado?", "options": {"a": "Loperamida (Imodium).", "b": "Vancomicina oral ou Fidaxomicina.", "c": "Amoxicilina.", "d": "Ciprofloxacino.", "e": "Dieta rica em fibras apenas."}, "answer": "b", "rationale": "A colite pseudomembranosa por C. difficile é uma complicação do uso de antibióticos. O tratamento exige antibióticos específicos que ajam no lúmen intestinal (Vancomicina oral) e suspensão do antibiótico causador se possível.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Tratamento de escolha atualizado.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Infectologia", "Pós-operatório", "C. difficile", "Tratamento"]}', 220, 'draft')
